// Input arrives as a JSON string in chatInput, sent by the onboarding skill via the n8n MCP.
// Expected: { "name": "Full Name", "email": "x@efuturemedia.com", "role": "Role",
//             "projects": "Realchecker" or ["A","B"], "channels": ["cross-devops", ...],
//             "firstName": "optional", "test": false }
const raw = $('Called by onboarding skill').first().json.chatInput;
let input;
try { input = JSON.parse(raw); } catch (e) { throw new Error('chatInput is not valid JSON: ' + raw); }

function str(v) { return v === null || v === undefined ? '' : String(v).trim(); }
const name = str(input.name);
const email = str(input.email);
const role = str(input.role);
const projects = Array.isArray(input.projects) ? input.projects.map(str).filter(Boolean).join(', ') : str(input.projects);
if (!name) { throw new Error('Missing "name"'); }
if (!email || email.indexOf('@') < 0) { throw new Error('Missing or invalid "email"'); }
if (!role) { throw new Error('Missing "role"'); }
if (!Array.isArray(input.channels)) { throw new Error('"channels" must be an array of channel names (can be empty)'); }
const channels = input.channels.map(function (c) { return str(c).replace(/^#/, ''); }).filter(Boolean);
const firstName = str(input.firstName) || name.split(/\s+/)[0];
const isTest = input.test === true;

// Settings live in the onboarding_settings data table so recipients can change without editing this workflow.
const settings = {};
const rows = $input.all();
for (let i = 0; i < rows.length; i++) {
  const r = rows[i].json;
  if (r && r.setting_key) { settings[r.setting_key] = str(r.setting_value); }
}
const recipientSetting = isTest ? settings.test_recipient : settings.channel_check_recipients;
if (!recipientSetting) { throw new Error('onboarding_settings has no value for ' + (isTest ? 'test_recipient' : 'channel_check_recipients')); }
const recipients = recipientSetting.split(',').map(str).filter(Boolean);

let text = (isTest ? '[TEST] ' : '') + 'A Slack account for *' + name + '* (' + email + ') has been created. Please check that they have access to the needed Slack channels.\n';
text += 'Role: ' + role + (projects ? ' · Projects: ' + projects : '') + '\n';
text += 'Based on the channels Antonio is part of, these were the channels suggested for ' + firstName + ':\n';
if (channels.length === 0) {
  text += '- none of Antonio\'s channels matched';
} else {
  text += channels.map(function (c) { return '- #' + c; }).join('\n');
}

return recipients.map(function (r) { return { json: { recipientEmail: r, text: text, test: isTest, newcomer: name } }; });

const sent = $input.all();
const built = $('Build channel-check message').all();
const lines = [];
for (let i = 0; i < sent.length; i++) {
  const s = sent[i].json;
  const b = built[i] ? built[i].json : {};
  if (!s.ok) { throw new Error('Slack did not confirm the DM to ' + (b.recipientEmail || 'recipient ' + i)); }
  lines.push('Sent to ' + b.recipientEmail + ' (channel ' + s.channel + ', ts ' + s.message_timestamp + ')');
}
return [{ json: { output: (built[0] && built[0].json.test ? '[TEST] ' : '') + lines.join('; ') } }];

